perl - <<'PERL'
use strict;
use warnings;

my $root = '/bench/repo';

my @entities = qw(
  User Memo Attachment Reaction Inbox MemoRelation MemoShare
  UserIdentity UserSetting IdentityProvider InstanceSetting
);

# collect non-store go files (exclude store/ entirely as "data layer")
my @files;
open my $find, '-|', "find", $root, "-name", "*.go", "-not", "-path", "*/proto/gen/*" or die;
while (<$find>) {
  chomp;
  next if /_test\.go$/;
  next if m{/store/};  # outside data layer
  push @files, $_;
}
close $find;

sub pkg_of {
  my ($path) = @_;
  open my $f, '<', $path or return undef;
  my $pkg;
  while (<$f>) { if (/^package\s+(\w+)/) { $pkg = $1; last } }
  close $f;
  my ($dir) = $path =~ /^(.*)\/[^\/]+$/;
  return "$dir";  # use directory as package identity (unique per go package dir)
}

my %type_pkgs;
for my $t (@entities) {
  my %pkgs;
  for my $f (@files) {
    open my $fh, '<', $f or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    next unless $content =~ /\bstore\.$t\b|\*store\.$t\b/;
    my $pkg = pkg_of($f);
    $pkgs{$pkg} = 1 if $pkg;
  }
  $type_pkgs{$t} = scalar keys %pkgs;
}

my @ranked = sort { $type_pkgs{$b} <=> $type_pkgs{$a} } @entities;
print "Rankings:\n";
for my $t (@ranked) {
  print "$type_pkgs{$t}\t$t\n";
}

# show top 2 package lists
for my $t ($ranked[0], $ranked[1]) {
  next unless $t;
  print "\n$t packages:\n";
  my %pkgs;
  for my $f (@files) {
    open my $fh, '<', $f or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    next unless $content =~ /\bstore\.$t\b|\*store\.$t\b/;
    my $pkg = pkg_of($f);
    $pkgs{$pkg} = 1 if $pkg;
  }
  for (sort keys %pkgs) {
    s/^\Q$root\E\/?//;
    print "  $_\n";
  }
}
PERL

